module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);
    wire [31:0] a_signed, b_signed;
    reg [31:0] res;
    assign a_signed = a;
    assign b_signed = b;
    assign r = res[31:0];
    assign zero = (res[31:0] == 0);
    assign negative = res[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? ((aluc == SLT) ? ($signed(a) < $signed(b)) : (a < b)) : 1'b0;
    always @(*) begin
        case(aluc)
            ADD: res <= $signed(a_signed) + $signed(b_signed);
            ADDU: res <= a + b;
            SUB: res <= $signed(a_signed) - $signed(b_signed);
            SUBU: res <= a - b;
            AND: res <= a & b;
            OR: res <= a | b;
            XOR: res <= a ^ b;
            NOR: res <= ~(a | b);
            SLT: res <= ($signed(a_signed) < $signed(b_signed)) ? 1 : 0;
            SLTU: res <= (a < b) ? 1 : 0;
            SLL: res <= b << a[4:0];
            SRL: res <= b >> a[4:0];
            SRA: res <= $signed(b) >>> a[4:0];
            SLLV: res <= b << a[4:0];
            SRLV: res <= b >> a[4:0];
            SRAV: res <= $signed(b) >>> a[4:0];
            LUI: res <= {a[31:16], 16'h0};
            default: res <= 32'hxxxxxxxx;
        endcase
    end

    assign carry = (aluc == ADD || aluc == SUB) ? ((res[31] != a_signed[31]) && (res[31] != b_signed[31])) : 1'bz;
    assign overflow = (aluc == ADD || aluc == SUB) ? (a_signed[31] == b_signed[31] && res[31] != a_signed[31]) : 1'bz;
endmodule
